import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"人才培养","description":"","frontmatter":{},"headers":[],"relativePath":"ai-dive/develop.md","filePath":"ai-dive/develop.md","lastUpdated":null}'),o={name:"ai-dive/develop.md"};function r(d,a,h,n,p,s){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="人才培养" tabindex="-1">人才培养 <a class="header-anchor" href="#人才培养" aria-label="Permalink to &quot;人才培养&quot;">​</a></h1><h2 id="选择应届生" tabindex="-1">选择应届生 <a class="header-anchor" href="#选择应届生" aria-label="Permalink to &quot;选择应届生&quot;">​</a></h2><h3 id="缺乏安全感" tabindex="-1">缺乏安全感 <a class="header-anchor" href="#缺乏安全感" aria-label="Permalink to &quot;缺乏安全感&quot;">​</a></h3><p>从学校进入职场是人生的重要转变之一，任何人在面对这种重要的转变时，都会缺乏安全感。因此，能够遇到一位导师对于应届毕业生来说是莫大的幸运，毕业生会极其珍惜这样的机会并非常尊重这位导师。</p><h3 id="可塑性强" tabindex="-1">可塑性强 <a class="header-anchor" href="#可塑性强" aria-label="Permalink to &quot;可塑性强&quot;">​</a></h3><p>工作以后，大家都会发现在学校里学的知识和实际工作基本上是没有关联的，因此应届毕业生就像是一张白纸，可塑性极强。在这种情况下，导师更容易为他们传授自身的技能，而且应届毕业生也更愿意接受和学习。如果一个人已经有工作经验的话，那么一定会和导师在理念或工作习惯上有很多不同，应届毕业生基本上不存在这样的问题。</p><h3 id="有学习的态度、主动性更强" tabindex="-1">有学习的态度、主动性更强 <a class="header-anchor" href="#有学习的态度、主动性更强" aria-label="Permalink to &quot;有学习的态度、主动性更强&quot;">​</a></h3><p>刚进入职场的毕业生是抱有学习态度的，他们有年轻的身体和积极的心态，能够更好地融入工作中。至少大多数时候他们还是很听导师话的，导师告诉他们一件事情，他们一定会按照导师的想法和思路去执行，而不会和导师反复讨论或对着干。虽然完全听话并不一定是一件好事，但是对于应届毕业生来说，按照前辈的指示去完成一件事情是极其重要的，因为新人首先要做的事情就是执行，执行能够让新人快速摸索出一条道路，主动地提出自己的意见。如果新人什么都没做就开始提意见，那就证明这个人太浮躁。</p><h2 id="如何更好地培养应届毕业生" tabindex="-1">如何更好地培养应届毕业生 <a class="header-anchor" href="#如何更好地培养应届毕业生" aria-label="Permalink to &quot;如何更好地培养应届毕业生&quot;">​</a></h2><h3 id="让其加入具体的项目" tabindex="-1">让其加入具体的项目 <a class="header-anchor" href="#让其加入具体的项目" aria-label="Permalink to &quot;让其加入具体的项目&quot;">​</a></h3><p>产品经理如果想要更好地培养人才，就一定要把人才放到具体的项目中，这是最有效的方法。因此，应届毕业生除了帮忙做一些日常、琐碎的工作，还要参与具体的项目。</p><p>在参与项目时，产品经理要让应届毕业生了解以下内容。</p><ol><li>为什么要做这个项目？即项目的背景、目标。</li><li>这个项目都需要哪些人参与？即项目组的构成和合作。</li><li>项目组成员是如何分工的，他们的责任分别是什么？即不同岗位的职责。</li><li>整个项目的流程是怎样的？即项目的流程管理和周期。</li><li>项目中的关键事项是什么？即更清晰的项目目标和管理。</li></ol><p>产品经理还要告诉应届毕业生了解以上内容的方法。</p><ol><li>主动和导师沟通，了解整个项目的流程。</li><li>主动要求参与项目，并输出会议纪要及项目每天的进度。</li><li>主动和参与项目的每一个人沟通，了解他们的工作职责。</li><li>主动承担项目中的脏活、累活和一些不起眼的小事，包括项目组的会议室预订、会议纪要输出、项目每天的跟进和更新、会议的召集、拿外卖等，简单来说就是要完全融入项目组。</li></ol><p>产品经理要带领应届毕业生参与项目，同时也要将自己和他们进行绑定，让他们有问题第一时间找自己解决。</p><h3 id="督促他们主动进行分析、总结" tabindex="-1">督促他们主动进行分析、总结 <a class="header-anchor" href="#督促他们主动进行分析、总结" aria-label="Permalink to &quot;督促他们主动进行分析、总结&quot;">​</a></h3><p>善于分析、总结是每一个产品经理必备的能力，对于应届毕业生来说也不例外。因此，产品经理除了要带领应届毕业生参与具体的项目，还要让他们学会在工作中主动进行分析、总结。那么，要分析、总结什么呢？主要包括以下三个方面的内容。</p><ol><li>做竞争对手的产品分析，可以以周为单位输出竞争对手的分析报告。</li><li>收集行业内的新闻资讯和好文章，并第一时间在群里进行分享。</li><li>按照项目、时间或其他方式输出总结，包括在某个时间具体做了什么事情、达到了什么效果、实施过程中存在的问题有哪些、有针对性的改进意见、其他注意事项等。</li></ol><p>产品经理要让应届毕业生主动地去发声、更多地去参与，这也代表着产品经理自己有更多的发声和参与，能够进一步地提升产品经理在这个团队中的影响力。</p><h3 id="强调数据的重要性" tabindex="-1">强调数据的重要性 <a class="header-anchor" href="#强调数据的重要性" aria-label="Permalink to &quot;强调数据的重要性&quot;">​</a></h3><p>产品经理还需要给应届毕业生强调数据的重要性。虽然应届毕业生短期内很难真正地通过数据化落地一些具体的解决方案，但是现阶段他们要做的是养成看数据的习惯。因此，产品经理要让应届毕业生每天一到办公室就先看 30 分钟的数据，并定期对他们进行抽查。</p>',22)])])}const _=e(o,[["render",r]]);export{u as __pageData,_ as default};
